import sys

def solve():
    tokens = sys.stdin.read().split()
    if not tokens:
        return
    n = int(tokens[0])
    arr = [int(x) for x in tokens[1:n+1]]
    arr.sort()
    triplets = set()
    for i in range(n - 2):
        left = i + 1
        right = n - 1
        while left < right:
            s = arr[i] + arr[left] + arr[right]
            if s == 0:
                triplets.add((arr[i], arr[left], arr[right]))
                left += 1
                right -= 1
            elif s < 0:
                left += 1
            else:
                right -= 1
    print(len(triplets))

if __name__ == '__main__':
    solve()

